installer-gui-script.script:
// See https://developer.apple.com/documentation/installer_js
function installation_check() {
  try {
    // Apple Silicon reports this even when Installer runs under Rosetta.
    if (system.sysctl("hw.optional.arm64") == 1) {
      my.result.title = "This package is for Intel Macs";
      my.result.message = "Apple Silicon Macs should use the official Homebrew installer from https://brew.sh instead.";
      my.result.type = "Fatal";
      return false;
    }
  } catch (error) {
    // Intel Macs do not have the sysctl at all.
  }
  return true;
}
